   195→  const [history, setHistory] = useState<FlexHistoryItem[]>(() => {
   196→    try {
   197→      const raw = localStorage.getItem(HISTORY_KEY);
   198→      return raw ? (JSON.parse(raw) as FlexHistoryItem[]) : [];
   199→    } catch {
   200→      return [];
   201→    }
   202→  });
   203→  const persistHistory = (list: FlexHistoryItem[]) => {
   204→    setHistory(list);
   205→    try {
   206→      localStorage.setItem(HISTORY_KEY, JSON.stringify(list));
   207→    } catch {
   208→      // 存储不可用时仅本次会话生效
   209→    }
   210→  };
   211→
   212→  // ---------- 字段添加 ----------
   213→  const addField = (column: string, zone?: DropZone) => {
   214→    const col = tableSchema?.columns.find((c) => c.name === column);
   215→    if (!col) return;
   216→    const target: DropZone = zone || (col.type === 'number' ? 'measure' : 'dimension');
   217→    if (target === 'dimension') {
   218→      if (dimensions.includes(column)) return showToast('该维度已在分组区中');
   219→      setDimensions((prev) => [...prev, column]);
   220→    } else if (target === 'measure') {
   221→      setMeasures((prev) => [...prev, { column, agg: 'SUM' }]);
   222→      // 首个指标且未设排序：默认按该指标降序（沿用 v0.4.9 行为）
   223→      if (!orderBy) setOrderBy({ by: measureAlias({ column, agg: 'SUM' }), dir: 'desc' });
   224→    } else if (target === 'having') {
   225→      setHavings((prev) => [...prev, { column, agg: 'SUM', op: '>', value: '' }]);
   226→    } else {
   227→      setFilters((prev) => [...prev, { column, op: '=', value: '' }]);
   228→    }
   229→  };
   230→
   231→  const handleDrop = (zone: DropZone, e: React.DragEvent) => {
   232→    e.preventDefault();
   233→    setDragOverZone(null);
   234→    const column = e.dataTransfer.getData('text/plain');
   235→    if (column) addField(column, zone);
   236→  };

