() => {
  const zones = {
    filter: '拖入字段添加筛选',
    having: '拖入指标字段添加聚合后条件',
    dimension: '拖入维度字段',
    measure: '拖入指标字段（',
  };
  function dropTo(zoneKey, column) {
    const ph = [...document.querySelectorAll('p')].find(p => p.textContent && p.textContent.includes(zones[zoneKey]));
    if (!ph) return { ok:false, reason:'placeholder not found for '+zoneKey };
    const zone = ph.parentElement;
    const dt = new DataTransfer();
    dt.setData('text/plain', column);
    const ev = new DragEvent('drop', { bubbles:true, cancelable:true, dataTransfer: dt });
    zone.dispatchEvent(ev);
    return { ok:true, zone: zoneKey, column };
  }
  return dropTo('filter', 'BNTFJE');
}

() => {
  function setSelect(select, value) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, 'value').set;
    setter.call(select, value);
    select.dispatchEvent(new Event('change', { bubbles: true }));
  }
  // find operator select (has BETWEEN option) in filter zone
  const selects = [...document.querySelectorAll('select')];
  const opSel = selects.find(s => [...s.options].some(o => o.value === 'BETWEEN'));
  if (!opSel) return { ok:false, reason:'operator select not found' };
  setSelect(opSel, 'BETWEEN');
  return { ok:true, value: opSel.value };
}

() => {
  function setInput(el, value) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, value);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  }
  const inputs = [...document.querySelectorAll('input')];
  const range = inputs.find(i => (i.placeholder||'').includes('区间'));
  if (!range) return { ok:false, reason:'range input not found', placeholders: inputs.map(i=>i.placeholder) };
  setInput(range, '1, 999999999999');
  return { ok:true, value: range.value, placeholder: range.placeholder };
}

() => {
  const inputs = [...document.querySelectorAll('input')];
