    select.dispatchEvent(new Event('change', { bubbles: true }));
  }
  const selects = [...document.querySelectorAll('select')];
  const dirSel = selects.find(s => [...s.options].map(o=>o.value).includes('asc') && [...s.options].map(o=>o.value).includes('desc'));
  if (!dirSel) return { ok:false, reason:'dir select not found' };
  setSelect(dirSel, 'asc');
  return { ok:true, dir: dirSel.value };
}

() => {
  const sqlEls = [...document.querySelectorAll('*')].filter(e=>e.children.length===0 && /SELECT `/.test(e.textContent||''));
