    });
  }, 2500);
})

() => {
  const t = [...document.querySelectorAll('table')].pop();
  if (!t) return { ok:false };
  const head = [...t.querySelectorAll('thead th')].map(x=>x.textContent.trim());
  const rows = [...t.querySelectorAll('tbody tr')].slice(0,5).map(r=>[...r.querySelectorAll('td')].map(c=>c.textContent.trim()));
  return { head, rows, rowCount: t.querySelectorAll('tbody tr').length };
}

