() => {
  const setSelect = (sel, val) => {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, 'value').set;
    setter.call(sel, val);
    sel.dispatchEvent(new Event('change', { bubbles: true }));
  };
  const tableSel = [...document.querySelectorAll('select')].find(s => [...s.options].some(o => o.textContent.includes('主营业务')));
  if (!tableSel) return { err: 'no table select - page state: ' + document.body.innerText.slice(0, 100) };
  const opt = [...tableSel.options].find(o => o.textContent.includes('主营业务'));
  setSelect(tableSel, opt.value);
  return 'ok';
}

() => {
