  if (!label) return { err: 'no history label' };
  // 历史记录条目：含「还原」按钮
  const restoreBtns = [...document.querySelectorAll('button')].filter(b => b.textContent.trim() === '还原');
  const info = restoreBtns.map(b => {
    const card = b.closest('div[class*="border"]') || b.parentElement.parentElement;
    return card ? card.textContent.trim().slice(0, 120) : b.parentElement.textContent.trim();
  });
  return { count: restoreBtns.length, info };
}

